type TextHighlightElementProps = Omit<
  ComponentProps<typeof TextHighlightScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const TextHighlightDefaults = {
  before: "Powered by ",
  highlight: "Northwind",
  after: "",
  preset: "marker",
  baseColor: "#101828",
  accentColor: "#266DF0",
  highlightedTextColor: "#101828",
  replaceWith: "Acme",
  startAt: 6,
  drawDuration: 14,
  thickness: 4,
  shineColor: "#FAFAFA",
  logoScale: 1.05,
  spinTurns: 1,
  holdDuration: 12,
  rushDuration: 24,
  rushScale: 42,
  rushDrift: 0.55,
  swingOut: 0.25,
  coverColor: "#266DF0",
  fontSize: 56,
  fontWeight: 600,
  speed: 1,
} satisfies Partial<TextHighlightElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const TextHighlightSchema = {
  before: {
    type: "text-content",
    default: "Powered by ",
    description: "Before",
  },
  highlight: {
    type: "text-content",
    default: "Northwind",
    description: "Highlight / wordmark",
  },
  after: { type: "text-content", default: "", description: "After" },
  baseColor: {
    type: "color",
    default: "#101828",
    description: "Base color",
    keyframable: false,
  },
  accentColor: {
    type: "color",
    default: "#266DF0",
    description: "Accent color",
    keyframable: false,
  },
  highlightedTextColor: {
    type: "color",
    default: "#101828",
    description: "Highlighted text color",
    keyframable: false,
  },
  fontSize: {
    type: "number",
    default: 56,
    min: 12,
    max: 160,
    step: 1,
    description: "Font size",
    hiddenFromList: false,
    keyframable: false,
  },
  fontWeight: {
    type: "number",
    default: 600,
    min: 400,
    max: 700,
    step: 100,
    description: "Font weight",
    hiddenFromList: false,
    keyframable: false,
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function TextHighlightFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const TextHighlightInner = forwardRef<
  HTMLDivElement,
  TextHighlightElementProps
>(({ style, ...props }, ref) => {
  // The layer's length, from the Sequence `wrapInSequence` puts around this.
  const { durationInFrames } = useVideoConfig();
  const rest = { ...TextHighlightDefaults, ...props };
  // The scene measures its copy once, on mount. An Inspector edit changes the
  // props without remounting it, so the key does.
  const key = JSON.stringify(props, (k, v) =>
    k === "children" ? undefined : v,
  );

  // width/height are what useVideoConfig() reports inside this Sequence, so
  // the scene lays itself out in its stage rather than the whole composition.
  // It is not a layer of its own: the one Studio shows is the wrapper's.
  return (
    <Sequence
      layout="none"
      showInTimeline={false}
      durationInFrames={durationInFrames}
      width={860}
      height={120}
    >
      <div
        ref={ref}
        style={{
          position: "relative",
          width: 860,
          height: 120,
          color: "black",
          fontFamily: "initial",
          fontSize: 16,
          fontStyle: "normal",
          fontVariant: "normal",
          fontWeight: 400,
          fontStretch: "normal",
          fontKerning: "auto",
          fontFeatureSettings: "normal",
          fontVariationSettings: "normal",
          lineHeight: "normal",
          letterSpacing: "normal",
          wordSpacing: "normal",
          textAlign: "start",
          textIndent: 0,
          textTransform: "none",
          textShadow: "none",
          textRendering: "auto",
          whiteSpace: "normal",
          wordBreak: "normal",
          overflowWrap: "normal",
          hyphens: "manual",
          direction: "ltr",
          visibility: "visible",
          ...style,
        }}
      >
        <TextHighlightFade>
          <TextHighlightScene key={key} {...rest} />
        </TextHighlightFade>
      </div>
    </Sequence>
  );
});

export const TextHighlight = Interactive.withSchema({
  Component: TextHighlightInner,
  componentName: "<TextHighlight>",
  schema: TextHighlightSchema,
  wrapInSequence: true,
});
